//! LrWorkspace PBS — PBS/Torque cluster job management.
//!
//! Implements the same job-lifecycle trait as the Slurm backend by wrapping
//! PBS commands (`qsub`, `qstat`, `qdel`) executed over SSH. Job scripts are
//! generated by the native command-array module in `lrworkspace-remote`.

use async_trait::async_trait;
use chrono::Utc;
use std::path::Path;
use std::sync::Arc;
use tracing::{info, instrument};

use lrworkspace_core::error::{CoreError, CoreResult};
use lrworkspace_core::safety::{normalize_remote_absolute, safe_join, shell_quote};
use lrworkspace_core::traits::SlurmManager;
use lrworkspace_core::types::*;

use lrworkspace_remote::RemoteExecutorImpl;

/// PBS/Torque implementation of the scheduler job lifecycle.
pub struct PbsManagerImpl {
    executor: Arc<RemoteExecutorImpl>,
    max_output_bytes: usize,
}

impl PbsManagerImpl {
    /// Create a new PBS manager.
    pub fn new(executor: Arc<RemoteExecutorImpl>) -> Self {
        Self {
            executor,
            max_output_bytes: 10 * 1024 * 1024, // 10 MB
        }
    }

    pub(crate) async fn submit_with_logs(&self,workspace:&Workspace,script_path:&Path,job_name:&str,stdout:&Path,stderr:&Path)->CoreResult<SlurmJob> {
        self.submit_internal(workspace,script_path,job_name,Some((stdout,stderr))).await
    }

    fn submission_command(work:&str,script:&Path,logs:Option<(&Path,&Path)>)->CoreResult<String> {
        let options=match logs {
            Some((out,err))=>format!(" -o {} -e {}",shell_quote(&normalize_remote_absolute(out)?),shell_quote(&normalize_remote_absolute(err)?)),
            None=>String::new(),
        };
        Ok(format!("cd {} && qsub{} {} 2>&1",shell_quote(work),options,shell_quote(&script.to_string_lossy())))
    }

    async fn submit_internal(&self,workspace:&Workspace,script_path:&Path,job_name:&str,logs:Option<(&Path,&Path)>)->CoreResult<SlurmJob> {
        info!(
            "Submitting PBS job: {} ({})",
            job_name,
            script_path.display()
        );

        let remote_script = safe_join(&workspace.remote_work_dir, script_path)?;
        let remote_work_dir = normalize_remote_absolute(&workspace.remote_work_dir)?;
        let cmd=Self::submission_command(&remote_work_dir,&remote_script,logs)?;

        let record = self
            .executor
            .execute_scheduler_control(workspace, &cmd, None, &Default::default())
            .await?;

        if record.exit_code != Some(0) {
            return Err(CoreError::Connection(format!(
                "qsub failed: stdout={} stderr={}",
                record.stdout.trim(),
                record.stderr.trim()
            )));
        }

        let job_id = Self::parse_job_id(&record.stdout).ok_or_else(|| {
            CoreError::Connection(format!(
                "qsub succeeded but no job id was found; the job may already be submitted, check before retrying: {}",
                record.stdout.trim()
            ))
        })?;

        let now = Utc::now();

        Ok(SlurmJob {
            workspace_id: workspace.id,
            triggered_by: AgentKind::CliAgent,
            job_id,
            submit_command: cmd,
            job_name: job_name.to_string(),
            submitted_at: now,
            state: SlurmJobState::Pending,
            stdout_log_path: logs.map(|(out,_)|out.to_path_buf()),
            stderr_log_path: logs.map(|(_,err)|err.to_path_buf()),
            exit_code: None,
        })
    }

    fn validate_job_id(job_id: &str) -> CoreResult<()> {
        if !job_id.is_empty()
            && job_id.chars().all(|c| {
                c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | '[' | ']' | ':')
            })
        {
            return Ok(());
        }
        Err(CoreError::Validation(format!(
            "Invalid PBS job id: {}",
            job_id
        )))
    }

    /// Preserve server/array suffixes. An unrelated warning number is not a job ID.
    fn parse_job_id(stdout: &str) -> Option<String> {
        fn candidate(token: &str) -> Option<String> {
            let token = token.trim_matches(|ch| matches!(ch, '\'' | '"' | ',' | ';'));
            let digits = token.bytes().take_while(u8::is_ascii_digit).count();
            if digits == 0 { return None; }
            let suffix = &token[digits..];
            if !suffix.is_empty() && !suffix.starts_with('.') && !suffix.starts_with('[') { return None; }
            if !token.bytes().all(|byte| byte.is_ascii_alphanumeric() || b"._-[]".contains(&byte)) { return None; }
            Some(token.into())
        }
        for line in stdout.lines() {
            let line = line.trim();
            if let Some(id) = candidate(line) { return Some(id); }
            let lower = line.to_ascii_lowercase();
            if lower.contains("job") && lower.contains("submitted") {
                if let Some(id) = line.split_whitespace().find_map(candidate) { return Some(id); }
            }
        }
        None
    }

    /// Read plain qstat fields and Torque's XML form (-x means XML there,
    /// whereas PBS Pro uses it to include finished job history).
    fn job_field<'a>(stdout: &'a str, key: &str) -> Option<&'a str> {
        if let Some(value)=stdout.lines().find_map(|line| {
            let (name,value)=line.trim().split_once('=')?;
            name.trim().eq_ignore_ascii_case(key).then_some(value.trim())
        }).filter(|value|!value.is_empty()) {return Some(value);}
        let lower=stdout.to_ascii_lowercase();let key=key.to_ascii_lowercase();
        let open=format!("<{key}>");let close=format!("</{key}>");
        let start=lower.find(&open)?+open.len();let end=start+lower[start..].find(&close)?;
        Some(stdout[start..end].trim()).filter(|value|!value.is_empty())
    }

    /// A missing job record does not prove success. PBS E is still exiting;
    /// terminal C/F records need Exit_status to distinguish success/failure.
    fn parse_single_job_state(stdout: &str) -> SlurmJobState {
        match Self::job_field(stdout, "job_state") {
            Some("Q" | "H" | "S" | "T" | "W") => SlurmJobState::Pending,
            Some("R" | "E" | "B") => SlurmJobState::Running,
            Some("C" | "F") => match Self::job_field(stdout, "Exit_status").and_then(|s| s.parse::<i32>().ok()) {
                Some(0) => SlurmJobState::Completed,
                Some(_) => SlurmJobState::Failed,
                None => SlurmJobState::Unknown("finished job has no Exit_status".into()),
            },
            Some(other) => SlurmJobState::Unknown(other.to_string()),
            None => SlurmJobState::Unknown("no job_state field; job may be unknown or history unavailable".into()),
        }
    }

    fn parse_job_state(stdout:&str)->SlurmJobState {
        let records:Vec<_>=if stdout.contains("<Job>") {
            stdout.split("<Job>").skip(1).collect()
        } else {stdout.split("Job Id:").skip(1).collect()};
        if records.len()<=1 {return Self::parse_single_job_state(stdout);}
        let has_children=records.iter().any(|record|record.lines().next().is_some_and(|header|header.split_once('[').is_some_and(|(_,rest)|rest.as_bytes().first().is_some_and(u8::is_ascii_digit))));
        let records:Vec<_>=records.into_iter().filter(|record|!has_children || !record.lines().next().unwrap_or("").contains("[]")).collect();
        records.into_iter().map(Self::parse_single_job_state).max_by_key(|state|match state {
            SlurmJobState::Running=>7,SlurmJobState::Pending=>6,SlurmJobState::Unknown(_)=>5,
            SlurmJobState::Failed=>4,SlurmJobState::Timeout=>3,SlurmJobState::Cancelled=>2,SlurmJobState::Completed=>1,
        }).unwrap_or_else(||SlurmJobState::Unknown("no job records".into()))
    }

    /// Parse `qstat -f -x` output (`Job_Name = my_job`).
    fn parse_job_name(stdout: &str) -> Option<String> {
        Self::job_field(stdout, "Job_Name").map(str::to_string)
    }

    /// Read one `#PBS -o`/`-e` log file under `<work>/. _lrworkspace_jobs/`.
    async fn read_log_file(
        &self,
        workspace: &Workspace,
        job_name: &str,
        suffix: &str,
    ) -> CoreResult<String> {
        let path = safe_join(
            &workspace.remote_work_dir,
            Path::new(&format!("._lrworkspace_jobs/{}.{}", job_name, suffix)),
        )?;
        let cmd = format!(
            "tail -c {} -- {} 2>/dev/null",
            self.max_output_bytes,
            shell_quote(&path.to_string_lossy())
        );
        let record = self
            .executor
            .execute_scheduler_control(workspace, &cmd, None, &Default::default())
            .await?;
        Ok(record.stdout)
    }
}

#[async_trait]
impl SlurmManager for PbsManagerImpl {
    #[instrument(skip(self, workspace))]
    async fn submit(
        &self,
        workspace: &Workspace,
        script_path: &Path,
        job_name: &str,
    ) -> CoreResult<SlurmJob> {
        self.submit_internal(workspace,script_path,job_name,None).await
    }

    #[instrument(skip(self, workspace))]
    async fn status(&self, workspace: &Workspace, job_id: &str) -> CoreResult<SlurmJobState> {
        Self::validate_job_id(job_id)?;

        // Torque keeps the array template running even after its elements
        // finish. Query concrete elements; unsupported PBS variants fall back.
        if job_id.contains("[]") {
            let command=format!("qstat -t -f {} 2>&1",shell_quote(job_id));
            let expanded=self.executor.execute_scheduler_control(workspace,&command,None,&Default::default()).await?;
            let concrete=expanded.stdout.lines().any(|line|line.trim().starts_with("Job Id:") && line.split_once('[').is_some_and(|(_,rest)|rest.as_bytes().first().is_some_and(u8::is_ascii_digit)));
            if expanded.exit_code==Some(0) && concrete {return Ok(Self::parse_job_state(&expanded.stdout));}
        }
        // Active jobs use portable plain text first. Only then request the
        // implementation-specific history/XML output. Unknown never means done.
        let command=format!("qstat -f {} 2>&1",shell_quote(job_id));
        let current=self.executor.execute_scheduler_control(workspace,&command,None,&Default::default()).await?;
        let state=Self::parse_job_state(&current.stdout);
        if current.exit_code==Some(0) && !matches!(state,SlurmJobState::Unknown(_)) {return Ok(state);}
        let command=format!("qstat -f -x {} 2>&1",shell_quote(job_id));
        let history=self.executor.execute_scheduler_control(workspace,&command,None,&Default::default()).await?;
        if history.exit_code==Some(0) {return Ok(Self::parse_job_state(&history.stdout));}
        let errors=format!("{} {} {} {}",current.stdout,current.stderr,history.stdout,history.stderr);
        if errors.to_ascii_lowercase().contains("unknown job") {return Ok(SlurmJobState::Unknown("job absent or history unavailable".into()));}
        Err(CoreError::Connection(format!("Cannot determine PBS job {job_id} status: {}",errors.trim())))

    }

    #[instrument(skip(self, workspace))]
    async fn cancel(&self, workspace: &Workspace, job_id: &str) -> CoreResult<()> {
        info!("Cancelling PBS job: {}", job_id);
        Self::validate_job_id(job_id)?;

        let cmd = format!("qdel {} 2>&1", shell_quote(job_id));
        let record = self
            .executor
            .execute_scheduler_control(workspace, &cmd, None, &Default::default())
            .await?;

        if record.exit_code != Some(0) {
            return Err(CoreError::Connection(format!(
                "Failed to cancel job {}: {}",
                job_id,
                record.stderr.trim()
            )));
        }

        Ok(())
    }

    #[instrument(skip(self, workspace))]
    async fn fetch_logs(
        &self,
        workspace: &Workspace,
        job_id: &str,
    ) -> CoreResult<(String, String)> {
        Self::validate_job_id(job_id)?;

        // Resolve the job name so we can find the #PBS -o/-e files written
        // under `<work>/. _lrworkspace_jobs/`.
        let name_cmd = format!("qstat -f -x {} 2>/dev/null", shell_quote(job_id));
        let name_record = self
            .executor
            .execute_scheduler_control(workspace, &name_cmd, None, &Default::default())
            .await?;
        let job_name = Self::parse_job_name(&name_record.stdout);

        let stdout = match &job_name {
            Some(name) => self.read_log_file(workspace, name, "out").await?,
            None => String::new(),
        };
        let stderr = match &job_name {
            Some(name) => self.read_log_file(workspace, name, "err").await?,
            None => String::new(),
        };
        Ok((stdout, stderr))
    }
}

#[cfg(test)]
mod tests {
    use super::*;



    #[test]
    fn array_template_does_not_hide_finished_element_states() {
        let complete="Job Id: 123[].server\n job_state = R\nJob Id: 123[1].server\n job_state = C\n exit_status = 0\n";
        assert_eq!(PbsManagerImpl::parse_job_state(complete),SlurmJobState::Completed);
        assert_eq!(PbsManagerImpl::parse_job_state(&complete.replace("exit_status = 0","exit_status = -2")),SlurmJobState::Failed);
    }

    #[test]
    fn scheduler_log_paths_are_single_argv_values_without_literal_directive_quotes() {
        #[cfg(windows)] let bash=r"C:\Program Files\Git\bin\bash.exe";
        #[cfg(unix)] let bash="bash";
        if !std::process::Command::new(bash).args(["-c","exit 0"]).status().is_ok_and(|s|s.success()){return;}
        let out=Path::new("/work/space ' quote/out/scheduler");let err=Path::new("/work/space ' quote/err/scheduler");let script=Path::new("/work/space ' quote/run.pbs");
        let cmd=PbsManagerImpl::submission_command("/",script,Some((out,err))).unwrap();
        let program=format!("qsub() {{ printf '%s\\n' \"$@\"; }}\n{cmd}");
        let output=std::process::Command::new(bash).args(["--noprofile","--norc","-c",&program]).output().unwrap();assert!(output.status.success());
        let text=String::from_utf8(output.stdout).unwrap();let args:Vec<_>=text.lines().collect();
        assert_eq!(args,vec!["-o","/work/space ' quote/out/scheduler","-e","/work/space ' quote/err/scheduler","/work/space ' quote/run.pbs"]);
    }

    #[test]
    fn torque_xml_and_mixed_array_records_are_not_misreported_as_completed() {
        assert_eq!(PbsManagerImpl::parse_job_state("<Data><Job><job_state>C</job_state><exit_status>2</exit_status></Job></Data>"),SlurmJobState::Failed);
        assert_eq!(PbsManagerImpl::parse_job_state("Job Id: 123[1].server\n job_state = C\n Exit_status = 0\nJob Id: 123[2].server\n job_state = R\n"),SlurmJobState::Running);
        assert_eq!(PbsManagerImpl::parse_job_state("<Data><Job><job_state>C</job_state><exit_status>0</exit_status></Job><Job><job_state>Q</job_state></Job></Data>"),SlurmJobState::Pending);
    }

    #[test]
    fn test_parse_job_id_formats() {
        assert_eq!(
            PbsManagerImpl::parse_job_id("12345.server"),
            Some("12345.server".into())
        );
        assert_eq!(
            PbsManagerImpl::parse_job_id("job submitted as 67890.x\n"),
            Some("67890.x".into())
        );
        assert_eq!(
            PbsManagerImpl::parse_job_id("Submitted job 712345"),
            Some("712345".into())
        );
        assert_eq!(PbsManagerImpl::parse_job_id("error: no job"), None);
        assert_eq!(PbsManagerImpl::parse_job_id("warning: 2026 changes\n12345[7].server\n"), Some("12345[7].server".into()));
        assert_eq!(PbsManagerImpl::parse_job_id("warning: 2048 bytes"), None);
        assert_eq!(PbsManagerImpl::parse_job_id("qsub: error 15007"), None);
    }

    #[test]
    fn test_parse_job_state_formats() {
        assert!(matches!(
            PbsManagerImpl::parse_job_state("    job_state = R\n"),
            SlurmJobState::Running
        ));
        assert!(matches!(
            PbsManagerImpl::parse_job_state("job_state = Q"),
            SlurmJobState::Pending
        ));
        assert!(matches!(
            PbsManagerImpl::parse_job_state("job_state = C\n Exit_status = 0"),
            SlurmJobState::Completed
        ));
        assert!(matches!(
            PbsManagerImpl::parse_job_state("qstat: Unknown Job Id 12345"),
            SlurmJobState::Unknown(_)
        ));
        assert!(matches!(
            PbsManagerImpl::parse_job_state(""),
            SlurmJobState::Unknown(_)
        ));
    }

    #[test]
    fn terminal_state_requires_successful_exit_status() {
        assert_eq!(PbsManagerImpl::parse_job_state("job_state = E\nExit_status = 0"), SlurmJobState::Running);
        assert_eq!(PbsManagerImpl::parse_job_state("job_state = F\nExit_status = 0"), SlurmJobState::Completed);
        assert_eq!(PbsManagerImpl::parse_job_state("job_state = C\nExit_status = 1"), SlurmJobState::Failed);
        assert_eq!(PbsManagerImpl::parse_job_state("job_state = F\nExit_status = -3"), SlurmJobState::Failed);
        assert!(matches!(PbsManagerImpl::parse_job_state("job_state = F"), SlurmJobState::Unknown(_)));
        assert!(matches!(PbsManagerImpl::parse_job_state("job_state = X"), SlurmJobState::Unknown(_)));
        assert!(matches!(PbsManagerImpl::parse_job_state("job_state_extra = R"), SlurmJobState::Unknown(_)));
        assert!(matches!(PbsManagerImpl::parse_job_state("qstat: cannot connect to server"), SlurmJobState::Unknown(_)));
    }

    #[test]
    fn test_parse_job_name() {
        assert_eq!(
            PbsManagerImpl::parse_job_name("    Job_Name = my_job\n"),
            Some("my_job".into())
        );
        assert_eq!(PbsManagerImpl::parse_job_name("no name here"), None);
    }

    #[test]
    fn test_validate_job_id_rejects_shell_syntax() {
        assert!(PbsManagerImpl::validate_job_id("12345.server").is_ok());
        assert!(PbsManagerImpl::validate_job_id("12345_7").is_ok());
        assert!(PbsManagerImpl::validate_job_id("12345;rm -rf /").is_err());
        assert!(PbsManagerImpl::validate_job_id("$(id)").is_err());
    }
}
